/* ------------------------------------------------------------------
   SERRATUS — brand-driven design
   Palette (lifted from the existing logo/poster assets)
     ink        #0A0A0A   page bg
     surface    #141414   card bg
     surfaceHi  #1B1B1B   raised card
     bone       #F5F3EE   primary text
     boneDim    #9C9A94   secondary text
     gold       #C6A046   primary accent
     goldBright #E9CB7C   hover / highlight
     goldDim    #2B2312   tinted gold surface
     line       rgba(245,243,238,0.09)
   Type — Archivo (900, wide, uppercase) for display, mirroring the
   poster's bold condensed headline; Inter for body; IBM Plex Mono
   for eyebrows, labels, stats — the same "certificate plate" voice
   as the poster's small print.
   Signature — the brand's own mark: two mirrored triangles forming
   an open X. Used as a section divider, a hover mark on cards, and
   inline beside the hero's highlighted tagline — never redrawn as
   something generic, always the shape they already brand with.
------------------------------------------------------------------- */

function Mark({ size = 28, className = "" }) {
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" className={className} fill="none">
      <path d="M2 2 L16 2 L2 16 Z" fill="currentColor" />
      <path d="M38 38 L24 38 L38 24 Z" fill="currentColor" />
      <path d="M2 38 L2 24 L16 38 Z" fill="none" stroke="currentColor" strokeWidth="1.4" />
      <path d="M38 2 L38 16 L24 2 Z" fill="none" stroke="currentColor" strokeWidth="1.4" />
    </svg>
  );
}

function useReveal() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      (entries) => entries.forEach((entry) => {
        if (entry.isIntersecting) { setVisible(true); obs.unobserve(entry.target); }
      }),
      { threshold: 0.16, rootMargin: "0px 0px -60px 0px" }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ as: Tag = "div", className = "", delay = 0, children, ...rest }) {
  const [ref, visible] = useReveal();
  return (
    <Tag ref={ref} className={`reveal ${visible ? "reveal--visible" : ""} ${className}`}
      style={{ transitionDelay: visible ? `${delay}ms` : "0ms" }} {...rest}>
      {children}
    </Tag>
  );
}

function CountUp({ to, suffix = "", duration = 1400 }) {
  const [ref, visible] = useReveal();
  const [val, setVal] = useState(0);
  useEffect(() => {
    if (!visible) return;
    let raf;
    const start = performance.now();
    const tick = (now) => {
      const p = Math.min(1, (now - start) / duration);
      setVal(Math.round(to * (1 - Math.pow(1 - p, 3))));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [visible, to, duration]);
  return <span ref={ref}>{val}{suffix}</span>;
}

